func maskRemote(raw string) string {
	raw = strings.TrimSpace(raw)
	if raw == "" {
		return "<unset>"
	}
	if !strings.Contains(raw, "://") {
		if at := strings.Index(raw, "@"); at != -1 {
			prefix := raw[:at]
			if colon := strings.Index(prefix, ":"); colon != -1 {
				return prefix[:colon] + ":***" + raw[at:]
			}
		}
		return raw
	}
	u, err := url.Parse(raw)
	if err != nil {
		return "***"
	}
	if u.User != nil {
		user := u.User.Username()
		if _, hasPass := u.User.Password(); hasPass {
			u.User = url.UserPassword(user, "***")
		} else if user != "" {
			u.User = url.User("***")
		}
	}
	if u.RawQuery != "" {
		q := u.Query()
		for k := range q {
			q.Set(k, "***")
		}
		u.RawQuery = q.Encode()
	}
	return strings.ReplaceAll(u.String(), "%2A", "*")
}

func firstNonEmpty(values ...string) string {
	for _, value := range values {
		if value != "" {
			return value
		}
	}
	return ""
}

func splitFiles(raw string) []string {
	parts := strings.FieldsFunc(raw, func(r rune) bool {
		return r == ',' || r == ';' || r == '\n'
	})
	files := make([]string, 0, len(parts))
	for _, part := range parts {
		part = strings.TrimSpace(part)
		if part != "" {
			files = append(files, part)
		}
	}
	return files
}

func parseBool(raw string) bool {
	switch strings.ToLower(strings.TrimSpace(raw)) {
	case "1", "true", "yes", "on":
		return true
	default:
		return false
	}
}

func normalizeVersion(version, prefix string) string {
	if prefix != "" {
		return strings.TrimPrefix(version, prefix)
	}
	return strings.TrimPrefix(version, "v")
}
